mapper.select:
SELECT * FROM mrp_terminal_demand WHERE run_id=#{runId} AND terminal_type <> 'MACHINE_OUTPUT'
AND (root_material_code LIKE CONCAT('%', #{keyword}, '%') OR terminal_material_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY factory_code, root_material_code, terminal_material_code, source_month, id LIMIT #{offset}, #{pageSize}

